import {sections,tokens,stages,terms,questions,tokenLoss,probability,initialDemo,demoTransition,gradeQuiz,updateCount,completionMessage} from './core.mjs';

const $=s=>document.querySelector(s);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey='minimind-lesson-1-v1';
let saved={completed:[],notes:''};
try{const loaded=JSON.parse(localStorage.getItem(storageKey)||'null');if(loaded&&typeof loaded==='object')saved={completed:Array.isArray(loaded.completed)?[...new Set(loaded.completed.filter(id=>sections.some(s=>s.id===id)))]:[],notes:typeof loaded.notes==='string'?loaded.notes:''};}catch{}
let quizLocked=new Set();
let current='map', stage=0, tokenPosition=4, demo=initialDemo(), records=null, recordIndex=0, chartMode='loss', answers={},submitted=false, selectedTerm=0, termPrinciples=null, toyParameter=0, termReturn='map', overviewIndex=0, causalEvidence=null, causalAnswer=null;
const save=()=>{try{localStorage.setItem(storageKey,JSON.stringify(saved));return true;}catch{return false;}};
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
function icon(type){const paths={
  data:'<rect x="6" y="4" width="19" height="24" rx="2"/><path d="M11 10h9M11 15h9M11 20h6"/>',
  dial:'<path d="M5 24a13 13 0 1 1 22 0M16 17l8-8"/><circle cx="16" cy="17" r="2"/><path d="M5 24h22"/>',
  network:'<circle cx="6" cy="7" r="3"/><circle cx="6" cy="25" r="3"/><circle cx="16" cy="16" r="3"/><circle cx="27" cy="7" r="3"/><circle cx="27" cy="25" r="3"/><path d="m9 9 5 5m-5 9 5-5m5-4 5-5m-5 9 5 5"/>',
  backward:'<path d="M27 10H12a7 7 0 0 0 0 14h13M13 4l-6 6 6 6"/>',
  update:'<path d="m8 19 7-7 9 7M15 12v15"/><path d="M5 6h22"/>',
  chart:'<path d="M5 4v24h24M8 22l6-9 6 4 7-11"/>',
  save:'<path d="M5 4h19l5 5v19H5zM10 4v8h13V4M10 28V18h13v10"/>',
  repeat:'<path d="M26 11A11 11 0 0 0 7 7L3 11m0-7v7h7M6 21a11 11 0 0 0 19 4l4-4m0 7v-7h-7"/>',
};return `<svg viewBox="0 0 32 32" aria-hidden="true">${paths[type]}</svg>`;}
function header(id,title,description,kicker){return `<div class="page-head"><span class="eyebrow">LESSON 01 / ${kicker}</span><div class="head-line"><h1>${title}</h1><span class="time-label">35–45 分钟 · 入门主线</span></div><p>${description}</p></div>`;}
function nextSection(){const i=sections.findIndex(s=>s.id===current),next=sections[i+1];return `<div class="section-next"><p>${saved.completed.includes(current)?'✓ 这一节已标记为理解':'完成探索后，用自己的话解释一次。'}</p><button class="primary-button" data-complete>${next?'我理解了，继续下一节 <span>→</span>':'记录自测通过 <span>✓</span>'}</button></div>`;}
function renderNav(){
  $('#navigation').innerHTML=sections.map((s,i)=>`<a href="#${s.id}" class="nav-item ${s.id===current?'active':''}" ${s.id===current?'aria-current="page"':''}><span class="nav-num">0${i+1}</span><span>${s.title}</span><span class="nav-check">${saved.completed.includes(s.id)?'✓':''}</span></a>`).join('');
  $('#current-section').textContent=sections.find(s=>s.id===current).title;
  $('#progress-text').textContent=`已完成 ${saved.completed.length} / 6`;
  $('#progress-fill').style.width=`${saved.completed.length/6*100}%`;
  $('.progress-track').setAttribute('aria-valuenow',saved.completed.length);
}
const overviewSteps=[
  ['准备题目','前文：春天到了，','目标：花','答案来自原文，不必为每个位置人工写标签。','tokens'],
  ['做预测','候选：花 / 雪 / …','模型分配概率','参数是模型内可调的数值，它们影响候选分数和概率。','tokens'],
  ['用目标判分','真实目标仍是：花','得到误差 loss','给“花”的概率越低，这一道题的误差代价越大。','tokens'],
  ['改参数，再试','先算梯度，再更新参数','重新预测，比较结果','梯度说明局部变化方向；优化器据此更新参数。不是看过题就会学习。','cycle']
];
function overviewPage(){return `<section class="surface lesson-panel"><div class="panel-title">第一遍：只看这四件事</div><p>点击一个动作，跟着“春天到了，花开了。”走一遍。</p><div class="overview-grid">${overviewSteps.map((x,i)=>`<button class="overview-step" data-overview="${i}" aria-pressed="${i===overviewIndex}"><span>0${i+1}</span><strong>${x[0]}</strong></button>`).join('')}</div><div id="overview-detail" class="overview-detail" aria-live="polite"></div></section><div class="callout-grid"><div class="callout"><h3>今天的目标</h3><p>能解释目标从哪来、误差怎么判，以及哪一步真正改变参数。先看懂一个小例子。</p></div><div class="callout"><h3>按自己的节奏</h3><p>默认主线约 35–45 分钟。代码、公式和工程细节可以展开；九个概念可随时查阅。</p></div></div>`;}
function renderOverview(){const x=overviewSteps[overviewIndex];$('#overview-detail').innerHTML=`<h2>${x[1]}</h2><p><strong>${x[2]}</strong> · ${x[3]}</p><a class="review-link" href="#${x[4]}">去动手观察 →</a>`;document.querySelectorAll('[data-overview]').forEach(e=>e.setAttribute('aria-pressed',Number(e.dataset.overview)===overviewIndex));}
function termHelp(indices){return `<div class="inline-terms">${indices.map(i=>`<details><summary>${terms[i][1]}是什么意思？</summary><p>${terms[i][2]}</p><button class="text-button" data-open-term="${i}">看完整解释与例子 →</button></details>`).join('')}</div>`;}
function evidenceStops(){return `<div class="evidence-stops"><article><h2>01 · 开始记录</h2><p>第一点已经是第 1100 批。它是随机初始化时的成绩吗？</p><details><summary>看解释</summary><p>不是。日志从恢复并跳过 1000 批后开始，第一条指标记录在 1100 批；没有记录最初 loss。</p></details><button class="soft-button" data-anchor="start" disabled>定位第一条记录</button></article><article><h2>02 · 两轮交界</h2><p>loss 从 2.0311 到 2.1673，是否说明学坏了？</p><details><summary>看解释</summary><p>不能这样判断。两条记录来自不同批次；第 2 轮继承已有参数，不会重新随机初始化。</p></details><button class="soft-button" data-anchor="boundary" disabled>定位第二轮首条记录</button></article><article><h2>03 · 训练结束</h2><p>最后一条 1.6360，能说明什么？</p><details><summary>看解释</summary><p>它是最后记录批次的 loss。轮数、批次位置及最终检查点共同确认训练完成；能力仍需独立评测。</p></details><button class="soft-button" data-anchor="end" disabled>定位最后一条记录</button></article></div>`;}
function syncSidebar(){const compact=window.matchMedia('(max-width:900px)').matches;$('#sidebar').inert=compact&&!$('#sidebar').classList.contains('open');}
window.matchMedia('(max-width:900px)').addEventListener('change',syncSidebar);
function mapPage(){return header('map','一段文字，<br>如何变成<span class="text-accent">会预测的模型</span>？','把文本变成练习题，让模型预测下一枚 token，用真实文本判分，再根据误差调整参数。第一遍只看四个动作，再用同一句话亲手试一次。','THE BIG PICTURE')+
`${overviewPage()}<details class="engineering"><summary>第二遍：展开正式脚本的 A–H 八步骤与训练配置</summary><section class="surface" aria-label="预训练流程互动地图"><div class="panel-top"><div><div class="panel-title">一批数据的学习旅程</div><div class="panel-subtitle">点击任一步骤，查看它的作用与代码</div></div><span class="pill">A → H · 反复循环</span></div><div class="map-layout"><div class="map-board"><div class="map-intro"><span>准备完成</span><span>模型、数据、分词器、优化器已就位 ↓</span></div><div class="flow-grid">${stages.map((s,i)=>`<button class="flow-node ${i===stage?'selected':''}" data-stage="${i}" aria-pressed="${i===stage}"><span class="node-letter">${s.letter}</span><span class="node-icon">${icon(s.icon)}</span><strong>${s.name}</strong><small>${s.en}</small></button>`).join('')}</div><div class="map-legend"><span>当前探索的步骤</span><span>点击节点自由跳转</span></div><div class="map-controls"><span class="step-count">STEP ${String(stage+1).padStart(2,'0')} / 08</span><div><button class="soft-button" data-stage-prev ${stage===0?'disabled':''} aria-label="上一个训练步骤">←</button> <button class="soft-button" data-stage-next>${stage===7?'从头再走一遍':'下一步 →'}</button></div></div></div><div class="detail-panel" id="stage-detail" aria-live="polite">${stageDetail()}</div></div></section>
<div class="facts-strip" aria-label="本次真实训练配置">${[['63.91','M','可学习参数','Dense · 8 层'],['32','条','每个小批次','每条最多 340 个位置'],['8','批','通常更新一次','轮末余数也更新'],['2','轮','已完成预训练','RTX 4090 · 24 GB']].map(v=>`<div class="fact"><div class="fact-label">${v[2]}</div><div class="fact-value">${v[0]}<small>${v[1]}</small></div><div class="fact-note">${v[3]}</div></div>`).join('')}</div><details class="surface preparation"><summary>开始这个循环前，程序要准备什么？</summary><p class="muted" style="font-size:12px;margin-top:12px">先读脚本下方的 __main__，再读上方的 train_epoch。定义函数不会立即训练；主程序准备好对象后才调用它。</p><ol class="prep-steps">${[['环境与种子','确定计算设备，控制初始化与打乱等随机过程。跨设备不保证逐位一致。'],['结构与断点','lm_config 是结构说明书。--from_resume 1 检测已有续训记录。'],['混合精度','给部分计算选择数值精度。本次云端默认 bf16，不是把所有对象都变成低精度。'],['实验记录','SwanLab 记录指标，不负责更新模型。恢复时可沿用 run ID。'],['建立三个对象','模型负责预测，Dataset 供应样本，AdamW 提供参数更新规则；分词器负责文本编号。'],['恢复原来状态','恢复模型、优化器、epoch 和 step。没有已有权重与断点时才从随机参数开始。'],['可选加速与多卡','compile 优化执行，多卡包装负责协作。当前实验是单卡，默认未开启 compile。'],['开始逐轮训练','每轮安排样本顺序，按批次调用 train_epoch，恢复的第一轮跳过已完成批次。'],['结束后清理','所有计划批次结束，保留权重和记录；多卡场景释放进程组。']].map(v=>`<li><strong>${v[0]}</strong><p>${v[1]}</p></li>`).join('')}</ol></details></details>${nextSection()}`;}
function stageDetail(){const s=stages[stage];return `<div class="detail-number">${s.letter} / ${s.en}</div><h3>${s.title}</h3><p>${s.text}</p><pre class="code-block">${escape(s.code)}</pre><div class="detail-why"><strong>记住这一点</strong>${s.why}<div class="source-actions"><a href="assets/train_pretrain.py" download>查看完整注释脚本 ↗</a></div></div>`;}
function tokenPage(){return header('tokens','答案，就在<span class="text-accent">原文里</span>。','全课使用“春天到了，花开了。”。先看题目与答案怎样错开一位，再观察参数怎样改变对“花”的预测。','NEXT-TOKEN PREDICTION')+
`${termHelp([0,2,3])}<section class="surface"><div class="panel-top"><div><div class="panel-title">春天到了，花开了。</div><div class="panel-subtitle">真实分词与编号 · 点击一个位置查看它的练习题</div></div><span class="pill">真实分词</span></div><div class="token-stage"><div class="tokens" id="token-sequence"></div><div class="token-legend"><span><i class="legend-key"></i>模型允许看到的前文</span><span><i class="legend-key orange"></i>老师用于判分的下一目标</span><span><i class="legend-key gray"></i>当前位置看不到的未来</span></div><div class="token-controls"><span class="range-label" id="position-label"></span><input id="token-position" type="range" min="0" max="9" value="${tokenPosition}" aria-label="选择输入 token 的位置"><button class="soft-button" id="token-next">下一位置 →</button></div><div class="token-result"><div class="result-box"><span class="result-label">模型可见的前文</span><div class="result-value" id="visible-prefix"></div></div><div class="result-box"><span class="result-label">原文给出的正确目标</span><div class="result-value target-value" id="target-token"></div></div></div><div class="explain-note" id="token-explanation"></div><details class="alignment"><summary>输入与标签明明一样，为什么不是抄答案？</summary><p>标签先复制输入，PAD 换成 −100。模型内部用第 t 个输出，与第 t+1 个标签判分。高亮列展示当前这一道题。</p><div class="table-scroll" id="alignment-table"></div><code>logits[:, :-1, :] ↔ labels[:, 1:]</code><p>整句一起处理，方便并行计算；每个位置仍受因果注意力限制。老师有答案，当前位置的模型看不到答案。</p></details></div></section>
<section class="surface lesson-panel"><h2>先猜，再验证：改动未来会影响前面的预测吗？</h2><p>预测“花”的位置只看到“春天到了，”。如果把更后面的“开”换成另一枚 token，这个位置的分数会变吗？</p><div class="button-row"><button class="soft-button" data-causal="yes">会改变</button><button class="soft-button" data-causal="no">不会改变</button></div><div id="causal-result" class="explain-note" role="status">先做出预测，再查看本机小模型的实测证据。</div></section>
<section class="surface lesson-panel" id="toy-lab"><span class="lesson-tag">教学模型 · 仅有“花”和“雪”两个候选，不是真实模型概率</span><h2>同一道题：春天到了，下一枚是“花”</h2><p>模型的参数是可调的数值。这里用一个参数 w 作为“花”的分数，“雪”的分数固定为 0。拖动 w，看两者的概率如何一起变化。</p><label for="toy-score">手动调参数 w（这里还没有自动学习）</label><input id="toy-score" type="range" min="-3" max="3" step="0.1" value="${toyParameter}"><div id="toy-result" aria-live="polite"></div><details class="math-detail"><summary>看看分数怎样变成概率，再变成 loss</summary><p>p(花) = exp(w) / (exp(w) + exp(0))；p(雪) = 1 − p(花)。两者加起来始终是 1。目标为“花”时，loss = −ln(p(花))。</p><p>正式模型对 6400 个候选一起计算。这里只保留两个候选，让你看清参数、分数、概率与误差的关系。</p></details><button class="primary-button" data-carry>带着这个参数，试一次自动更新 →</button></section>${nextSection()}`;}
function renderTokens(){
  if(!$('#token-sequence').children.length)$('#token-sequence').innerHTML=tokens.map((t,i)=>`<button class="token ${t.special?'special':''}" ${i===10?'disabled':''} data-token="${i}">${t.text}<small>ID ${t.id}</small></button>`).join('');
  document.querySelectorAll('[data-token]').forEach(e=>{const i=Number(e.dataset.token),t=tokens[i];e.classList.toggle('future',i>tokenPosition+1);e.classList.toggle('target',i===tokenPosition+1);e.classList.toggle('selected',i===tokenPosition);e.setAttribute('aria-pressed',i===tokenPosition);e.setAttribute('aria-label',`${t.text}，编号 ${t.id}${i===tokenPosition?'，当前输入位置':i===tokenPosition+1?'，预测目标':''}`);});
  $('#position-label').textContent=`位置 ${tokenPosition+1} / 10`;
  $('#token-position').value=tokenPosition;$('#token-position').setAttribute('aria-valuetext',`当前位置 ${tokens[tokenPosition].text}，下一目标 ${tokens[tokenPosition+1].text}`);
  $('#visible-prefix').textContent=tokenPosition===0?'BOS · 开始标记':`BOS · ${tokens.slice(1,tokenPosition+1).map(t=>t.text).join('')}`;
  const target=tokens[tokenPosition+1];$('#target-token').textContent=target.text==='PAD'?'PAD → 忽略（−100）':target.text==='EOS'?'EOS · 结束标记':target.text;
  $('#token-explanation').textContent=target.text==='PAD'?'文本已结束。PAD 的目标标签是 −100，不参与 loss；保留 EOS，让模型学习何时结束。':'橙色目标是老师拿来判分的答案。当前位置只能使用前文；因果注意力阻止它偷看目标和后面的内容。';
  const row=(title,values)=>`<tr><th scope="row">${title}</th>${values.map((v,i)=>`<td class="${i===tokenPosition?'aligned-current':''}">${v}</td>`).join('')}</tr>`;
  $('#alignment-table').innerHTML=`<table><caption>当前位置输出与下一位置目标对照（最后一个 PAD 输入没有下一目标，未列出）</caption><tbody>${row('输入位置 t',tokens.slice(0,-1).map(t=>t.text))}${row('原始 labels[t]',tokens.slice(0,-1).map(t=>t.id))}${row('判分目标 labels[t+1]',tokens.slice(1).map(t=>t.text==='PAD'?'−100 · 忽略':t.text))}</tbody></table>`;
}
function renderToy(){const p=probability(toyParameter);$('#toy-result').innerHTML=`<div class="prediction-cards"><div><span>花：分数 ${toyParameter.toFixed(1)}</span><strong>${(p*100).toFixed(1)}%</strong><meter min="0" max="1" value="${p}" aria-label="花的概率"></meter></div><div><span>雪：分数 0</span><strong>${((1-p)*100).toFixed(1)}%</strong><meter min="0" max="1" value="${1-p}" aria-label="雪的概率"></meter></div><div><span>正确目标是花 · loss</span><strong>${tokenLoss(p).toFixed(3)}</strong><small>给目标的概率越高，代价越小</small></div></div>`;$('#toy-score').setAttribute('aria-valuetext',`参数 ${toyParameter.toFixed(1)}，花的概率 ${(p*100).toFixed(1)}%`);}
async function checkCausal(answer){causalAnswer=answer;$('#causal-result').textContent='正在读取本机小模型的实测记录…';try{if(!causalEvidence){const r=await fetch('assets/micro-lab.json');if(!r.ok)throw new Error();causalEvidence=await r.json();}if(current!=='tokens')return;const e=causalEvidence.causal;$('#causal-result').textContent=`${causalAnswer==='no'?'判断正确。':'再想一下：当前位置看不到未来。'}改变后面的 token 后，前 5 个位置 logits 的最大差异为 ${e.prefix_max_difference}。这是同一个极小模型的两次前向实测，来自本机练习记录。修改位置及之后的最大差异为 ${e.changed_suffix_max_difference.toFixed(4)}。`; }catch{if(current==='tokens')$('#causal-result').textContent='实测记录读取失败，可下载本机练习脚本验证，或刷新后重试。';}}
function cyclePage(){return header('cycle','让下一次预测，<br><span class="text-accent">发生一点改变</span>。','仍然是“春天到了，”→“花”。先观察一次更新，再重新预测，检查概率和误差到底变了没有。','ONE TRAINING CYCLE')+
`${termHelp([1,4,5])}<section class="surface lesson-panel"><div class="panel-title">同一个两候选教学模型：花的分数 = w，雪的分数 = 0</div><p>先按①②③④走一遍。这里只用简单梯度下降，学习率为 0.8；正式训练使用 AdamW。</p><div class="mode-tabs button-row" role="group" aria-label="选择累积模式"><button data-accum="1" aria-pressed="${demo.accumulation===1}">入门：1 批更新</button><button data-accum="8" aria-pressed="${demo.accumulation===8}">进阶：8 批累积</button></div><p class="muted">切换模式或手动调参数会重新开始这段演示。</p><label for="demo-start">手动调起点 w：先试试调大与调小，各会怎样？</label><input type="range" id="demo-start" min="-3" max="3" step="0.1" value="${demo.parameter}" ${demo.phase!=='ready'||demo.batches?'disabled':''}><div class="demo-stats"><div><small>参数 w</small><strong id="demo-parameter"></strong></div><div><small>累积梯度</small><strong id="demo-gradient"></strong></div><div><small>更新次数</small><strong id="demo-updates"></strong></div></div><div class="demo-state"><p id="batch-label"></p><div class="batch-slots">${Array.from({length:demo.accumulation},(_,i)=>`<span class="batch-slot" data-slot="${i}"></span>`).join('')}</div></div><div class="demo-steps four-actions"><button class="demo-action" data-demo="forward">① 前向预测<span>得到概率与 loss</span></button><button class="demo-action" data-demo="backward">② 计算梯度<span>参数还不变</span></button><button class="demo-action" data-demo="step">③ 更新参数<span>w ← w − 0.8 × 梯度</span></button><button class="demo-action" data-demo="verify">④ 重新预测<span>检查更新后的结果</span></button></div><div class="demo-message" id="demo-message" role="status"></div><div id="demo-comparison" aria-live="polite"></div><div class="demo-bottom"><button class="soft-button" data-demo="fill" ${demo.accumulation===1?'hidden':''}>补齐剩余批次 →</button><button class="text-button" data-demo="reset">重置演示</button></div><details class="math-detail"><summary>梯度为什么是负的？为什么要减去梯度？</summary><p>这个教学模型的 loss 对 w 的梯度是 p(花) − 1。w = 0 时，p(花) = 0.5，梯度为 −0.5：在这里稍微增大 w，loss 会变小。简单梯度下降减去梯度，所以 w 变成 0 − 0.8 × (−0.5) = 0.4。</p><p>8 批模式把每批梯度除以 8 再累积。本示例每批重复同一个目标；真实训练的不同批次、有效 token 数和尾批会更复杂。</p></details></section>
<details class="surface preparation"><summary>把这个小实验扩展到你的正式训练</summary><p>正式模型有约 6391 万个参数、6400 个候选。前向给出预测，反向算梯度，AdamW 按自己的规则更新参数；这三种角色保持不变。</p><div class="frequency-list">${[['每批','预测与反向','得到误差并累积梯度'],['每 8 批','通常更新一次','32 × 8 = 256 条样本'],['每 100 批','记录一次指标','当前批次的 loss'],['每 1000 批','保存一次成果','模型与续训检查点']].map(v=>`<div class="frequency-row"><span>${v[0]}</span><div>${v[1]}<small>${v[2]}</small></div></div>`).join('')}</div><p>轮末余数也会更新、记录与保存。一轮 39,695 个小批次，更新 4,962 次；两轮更新 9,924 次。</p></details>
<details class="surface preparation"><summary>可选：在 Mac 上真实执行一次 PyTorch 更新</summary><p>从项目根目录运行下面命令。使用随机初始化的极小模型与项目分词器，不加载正式权重。会打印 token 对照、手工 loss 核验、参数变化和因果性检查。</p><pre class="code-block">.venv/bin/python scripts/lesson1_micro_lab.py</pre><div class="source-actions"><a href="assets/lesson1_micro_lab.py" download>下载练习脚本 ↓</a><a href="assets/micro-lab.json" download>下载本机实测记录 ↓</a></div><p>下载的脚本也需在完整 MiniMind 项目中运行。网页上方是两候选示意，此处是实际模型实现，两者数值不应混用。</p></details>${nextSection()}`;}
function renderDemo(){
  $('#demo-parameter').textContent=demo.parameter.toFixed(3);$('#demo-gradient').textContent=demo.gradient.toFixed(3);$('#demo-updates').textContent=demo.updates;
  $('#batch-label').textContent=`已累积 ${demo.batches} / ${demo.accumulation} 批 · ${demo.accumulation===1?'先看清一次更新':'每满 8 批才更新'}`;
  $('#demo-start').disabled=demo.phase!=='ready'||demo.batches>0;$('#demo-start').value=demo.parameter;$('#demo-start').setAttribute('aria-valuetext',`当前参数 ${demo.parameter.toFixed(3)}`);
  document.querySelectorAll('[data-slot]').forEach((e,i)=>e.classList.toggle('filled',i<demo.batches));
  $('#demo-message').textContent=demo.message;
  document.querySelectorAll('[data-demo]').forEach(e=>{const action=e.dataset.demo;e.disabled=action==='forward'?demo.phase!=='ready':action==='backward'?demo.phase!=='predicted':action==='step'?demo.phase!=='accumulated':action==='verify'?demo.phase!=='updated':action==='fill'?!(demo.phase==='ready'&&demo.batches>0&&demo.batches<demo.accumulation):false;e.classList.toggle('current',!e.disabled&&action!== 'fill'&&action!=='reset');});
  const row=(label,x)=>`<tr><th scope="row">${label}</th><td>${x?x.parameter.toFixed(3):'—'}</td><td>${x?(x.probability*100).toFixed(1)+'%':'待预测'}</td><td>${x?x.loss.toFixed(3):'待预测'}</td></tr>`;
  $('#demo-comparison').innerHTML=`<div class="table-scroll"><table><caption>同一道题的前后比较：目标都是“花”</caption><thead><tr><th>阶段</th><th>参数 w</th><th>花的概率</th><th>loss</th></tr></thead><tbody>${row('更新前的前向',demo.before)}${row('更新后重新前向',demo.after)}</tbody></table></div>${!demo.before?`<p>手动预览：w = ${demo.parameter.toFixed(3)} 时，花的概率为 ${(probability(demo.parameter)*100).toFixed(1)}%，loss 为 ${tokenLoss(probability(demo.parameter)).toFixed(3)}。点击①记录起点。</p>`:''}`;
}
function evidencePage(){return header('evidence','你完成的训练，<br>留下了<span class="text-accent">哪些证据</span>？','拖动位置，查看云端日志中的真实记录。曲线展示整体变化，每个记录点仍然只代表当时的一个小批次。','YOUR REAL EXPERIMENT')+
`${evidenceStops()}<section class="surface"><div class="panel-top"><div><div class="panel-title">RTX 4090 · 两轮预训练记录</div><div class="panel-subtitle">784 个真实记录点 · 从续训后 step 1100 开始</div></div><div class="mode-tabs" role="group" aria-label="选择曲线指标"><button class="${chartMode==='loss'?'active':''}" data-chart="loss" aria-pressed="${chartMode==='loss'}">Loss</button><button class="${chartMode==='lr'?'active':''}" data-chart="lr" aria-pressed="${chartMode==='lr'}">学习率</button></div></div><div id="evidence-body" class="empty-state" role="status">正在读取训练记录…</div></section><div class="callout-grid"><div class="callout"><h3>看到波动，不急着判断退化</h3><p>第一轮末 loss 2.0311，第二轮首个记录为 2.1673。它们来自不同批次；整体下降，并不要求每个批次都更低。</p></div><div class="callout"><h3>训练完成 ≠ 所有回答都正确</h3><p>最后一条 loss 1.6360 是当前批次误差，不是正确率，也不是验证集成绩。本次完整训练没有独立验证集。</p></div></div>${nextSection()}`;}
async function loadEvidence(){
  try{if(!records){const response=await fetch('assets/training-data.json');if(!response.ok)throw new Error('load');records=await response.json();}if(current!=='evidence')return;
    recordIndex=Math.min(recordIndex,records.points.length-1);$('#evidence-body').className='';$('#evidence-body').innerHTML=`<div class="chart-wrap"><svg id="training-chart" class="chart" viewBox="0 0 900 260" role="img" aria-label="真实训练指标曲线"></svg><div class="chart-selector"><span class="range-label">日志位置</span><input type="range" id="record-position" min="0" max="${records.points.length-1}" value="${recordIndex}" aria-label="选择训练日志记录"><button class="soft-button" id="record-start">起点</button><button class="soft-button" id="record-end">终点</button></div></div><div class="record-detail"><div class="record-stats" aria-live="polite"><div><div class="fact-label">轮次 / 本轮批次</div><div class="fact-value" id="record-epoch"></div></div><div><div class="fact-label">全局小批次</div><div class="fact-value" id="record-global"></div></div><div><div class="fact-label">当前批次 loss</div><div class="fact-value" id="record-loss"></div></div><div><div class="fact-label">学习率</div><div class="fact-value" id="record-lr"></div></div></div><div class="raw-log" id="raw-log"></div><div class="source-actions"><span id="update-count"></span><a href="assets/pretrain.log" download>下载原始日志 ↓</a><a href="https://github.com/Jenoqin/minimind/blob/b51c2d3/trainer/train_pretrain.py" target="_blank" rel="noopener noreferrer">对照训练代码 ↗</a></div></div>`;document.querySelectorAll('[data-anchor]').forEach(e=>e.disabled=false);renderChart();
  }catch{if(current==='evidence')$('#evidence-body').innerHTML='<div class="error-state">训练记录读取失败。请刷新页面重试，或直接<a href="assets/pretrain.log" download>下载原始日志</a>。</div>';}
}
function renderChart(){
  if(!records||current!=='evidence')return;document.querySelectorAll('[data-chart]').forEach(e=>{const on=e.dataset.chart===chartMode;e.classList.toggle('active',on);e.setAttribute('aria-pressed',on);});const points=records.points,p=points[recordIndex],x=s=>55+s/79390*815,max=chartMode==='loss'?6:.0005,y=v=>219-v/max*194;
  const path=points.map((p,i)=>`${i?'L':'M'}${x(p.global).toFixed(2)},${y(p[chartMode]).toFixed(2)}`).join(' ');
  let svg='';for(let i=0;i<=4;i++){const v=max*i/4,yy=y(v);svg+=`<line x1="55" y1="${yy}" x2="870" y2="${yy}"/><text x="43" y="${yy+4}" text-anchor="end">${chartMode==='loss'?v.toFixed(1):v===0?'0':v.toExponential(1)}</text>`;}
  for(const n of [0,20000,40000,60000,79390])svg+=`<text x="${x(n)}" y="245" text-anchor="middle">${n===0?'0':n===79390?'79,390':n/1000+'k'}</text>`;
  svg+=`<text x="870" y="258" text-anchor="end">全局小批次</text><path d="${path}" fill="none" stroke="${chartMode==='loss'?'#6b8c59':'#d18a58'}" stroke-width="1.6"/><line class="selected-line" x1="${x(p.global)}" y1="16" x2="${x(p.global)}" y2="219"/><circle cx="${x(p.global)}" cy="${y(p[chartMode])}" r="5" fill="#d4663f" stroke="white" stroke-width="2"/>`;
  $('#training-chart').innerHTML=svg;$('#training-chart').setAttribute('aria-label',`${chartMode==='loss'?'Loss':'学习率'}真实训练曲线，当前全局批次 ${p.global}，指标 ${p[chartMode]}`);
  $('#record-position').value=recordIndex;$('#record-epoch').textContent=`${p.epoch}/2 · ${p.step.toLocaleString()}`;$('#record-epoch').style.fontSize='16px';$('#record-global').textContent=p.global.toLocaleString();$('#record-loss').textContent=p.loss.toFixed(4);$('#record-lr').textContent=p.lr.toFixed(8);$('#record-lr').style.fontSize='16px';$('#raw-log').textContent=`源文件第 ${p.line} 行 · ${p.raw}`;$('#update-count').textContent=`至此约 ${updateCount(p).toLocaleString()} 次参数更新`;
}
function termsPage(){return header('terms','从问题出发，<br>理解<span class="text-accent">九个概念</span>。','给一段前文，预测下一枚 token；看到真实目标后，调整模型。从这个最小任务出发，看看每个概念为什么必须出现。','FIRST PRINCIPLES')+
`<p class="return-link"><a href="#${termReturn}">← 回到刚才的学习环节</a> · 这里是随时查阅的概念库，不必先背完定义。</p><div class="concept-roadmap"><p><strong>表示与学习</strong> token → 参数 → logits → loss → 梯度 → 优化器</p><p><strong>组织过程</strong> batch：一次取哪些样本 · step：处理到第几批 · epoch：遍历了几轮</p></div><div class="concept-tabs" role="group" aria-label="选择要理解的概念">${terms.map((t,i)=>`<button data-term="${i}" aria-pressed="${selectedTerm===i}" aria-controls="principle-detail" class="concept-tab ${selectedTerm===i?'selected':''}"><span>0${i+1}</span>${t[1]}<small>${t[0]}</small></button>`).join('')}</div><section class="surface principle-detail" id="principle-detail" aria-label="概念第一性原理解释" aria-live="polite"><p class="empty-state" role="status">正在读取概念讲解…</p></section><details class="surface preparation"><summary>开始训练前，三个对象有什么不同？</summary><div class="prep-grid"><p><strong>lm_config · 结构说明书</strong><br>规定层数、维度等。它不是学到的知识。</p><p><strong>model · 预测器</strong><br>内部有可学习参数，前向时根据前文预测。</p><p><strong>optimizer · 更新规则</strong><br>使用梯度修改参数，并维护自身状态。创建它不等于已经开始学习。</p></div></details><div class="callout-grid"><div class="callout"><h3>训练</h3><p>目标来自原文。预测 → 计算 loss → backward → 参数更新。</p></div><div class="callout"><h3>推理</h3><p>用已学到的参数选出下一枚 token，追加后继续预测。普通生成不更新参数。</p></div></div>${nextSection()}`;}
const formatTerm=s=>escape(s).replace(/`([^`]+)`/g,'<code>$1</code>');
async function loadTermPrinciples(){
  try{if(!termPrinciples){const response=await fetch('assets/term-principles.json');if(!response.ok)throw new Error('load');termPrinciples=await response.json();}if(current==='terms')renderTermPrinciple();}
  catch{if(current==='terms')$('#principle-detail').innerHTML='<div class="error-state">概念讲解读取失败，请刷新重试，或<a href="assets/lesson-1.md" download>下载完整讲义</a>。</div>';}
}
function renderTermPrinciple(){
  if(current!=='terms'||!termPrinciples)return;
  const t=terms[selectedTerm],p=termPrinciples[String(selectedTerm+1)];
  $('#principle-detail').innerHTML=`<div class="principle-heading"><span class="eyebrow">0${selectedTerm+1} / ${t[0]}</span><h2>${escape(t[1])}：${escape(p.title.split('：').slice(1).join('：'))}</h2><p>${t[2]}</p></div><div class="principle-body"><div class="principle-section"><span class="principle-label">01 · 为什么需要它？</span><p>${formatTerm(p.why)}</p></div><div class="principle-section"><span class="principle-label">02 · 本质是什么？</span><p>${formatTerm(p.essence)}</p></div><div class="principle-example"><span class="principle-label">03 · 用一个小例子理解</span><p>${formatTerm(p.example)}</p></div><div class="principle-section"><span class="principle-label">04 · 回到这次训练</span><p>${formatTerm(p.connection)}</p><code class="principle-code">${escape(t[3])}</code></div><details class="principle-question"><summary><span>检验理解</span>${escape(p.question)}</summary><p>${formatTerm(p.answer)}</p></details></div>`;
  document.querySelectorAll('[data-term]').forEach(e=>{const active=Number(e.dataset.term)===selectedTerm;e.classList.toggle('selected',active);e.setAttribute('aria-pressed',active);});
}
function quizPage(){return header('quiz','你能自己<span class="text-accent">解释一遍</span>吗？','用新句子和新情境检查理解。答错后可以回到对应练习，只重做错题。','CHECK YOUR UNDERSTANDING')+
`<form id="quiz-form"><div class="quiz-list">${questions.map((q,i)=>`<fieldset class="surface question ${submitted?(answers[i]===q.answer?'correct':'incorrect'):''}" id="question-${i}"><legend><span class="question-number">0${i+1}</span>${q.q}</legend><div class="question-content"><div class="answers">${q.options.map((a,j)=>`<label class="answer"><input type="radio" name="question-${i}" value="${j}" ${answers[i]===j?'checked':''} ${submitted||quizLocked.has(i)?'disabled':''} required><span>${a}</span></label>`).join('')}</div>${submitted||quizLocked.has(i)?`<p class="question-feedback">${answers[i]===q.answer?'✓ 理解正确。':'↗ 再想一想。'}${q.explain}${answers[i]!==q.answer?` <a class="review-link" href="#${q.section}">回到对应练习 →</a>`:''}</p>`:''}</div></fieldset>`).join('')}</div>${submitted?`<div class="quiz-result" role="status"><div><strong>${gradeQuiz(answers)} / ${questions.length}</strong><p>${gradeQuiz(answers)===questions.length?'你已把关键环节连起来了。再用自己的话讲一次。':'沿着题目解释，再去地图或演示中验证。'}</p></div>${gradeQuiz(answers)<questions.length?'<button type="button" class="soft-button" id="quiz-wrong">只重做错题 →</button>':''}<button type="button" class="soft-button" id="quiz-retry">全部重做 ↻</button></div>`:`<div class="quiz-actions"><span id="answered-count">已作答 ${Object.keys(answers).length} / ${questions.length}</span><button type="submit" class="primary-button">检查我的答案 →</button></div>`}</form><div class="finish-panel"><h3>最后，用 3 分钟讲清这条链路</h3><p class="chain">文本 → 分词 → 输入与标签 → 预测 → loss → 梯度 → 参数更新 → 保存 → 生成</p><p>能讲清原因，并指到代码位置，就完成了第一课。第二课再深入 token 与标签移位。</p><div class="source-actions"><button class="text-button" data-open-notes>把自己的解释写进笔记 ↗</button><a href="assets/lesson-1.md" download>下载完整讲义 ↓</a></div></div>${nextSection()}`;}
function render(){
  current=sections.some(s=>s.id===location.hash.slice(1))?location.hash.slice(1):'map';renderNav();
  const views={map:mapPage,tokens:tokenPage,cycle:cyclePage,evidence:evidencePage,terms:termsPage,quiz:quizPage};$('#main').innerHTML=`<div class="content-enter">${views[current]()}</div>`;
  if(current==='map')renderOverview();if(current==='tokens'){renderTokens();renderToy();}if(current==='cycle')renderDemo();if(current==='evidence')loadEvidence();if(current==='terms')loadTermPrinciples();
  $('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');syncSidebar();
}
document.addEventListener('click',event=>{
  if(event.target.closest('.skip-link')){event.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});return;}
  const b=event.target.closest('button');if(!b)return;
  if(b.dataset.stage!==undefined){stage=Number(b.dataset.stage);refreshMap();}
  if(b.hasAttribute('data-stage-prev')){stage=Math.max(0,stage-1);refreshMap();}
  if(b.hasAttribute('data-stage-next')){stage=(stage+1)%8;refreshMap();}
  if(b.dataset.overview!==undefined){overviewIndex=Number(b.dataset.overview);renderOverview();}
  if(b.dataset.openTerm!==undefined){termReturn=current==='terms'?termReturn:current;selectedTerm=Number(b.dataset.openTerm);location.hash='terms';if(current==='terms')renderTermPrinciple();}
  if(b.dataset.causal)checkCausal(b.dataset.causal);
  if(b.hasAttribute('data-carry')){demo=initialDemo(1,toyParameter);location.hash='cycle';}
  if(b.dataset.accum){demo=initialDemo(Number(b.dataset.accum));render();}
  if(b.dataset.anchor!==undefined&&records){recordIndex=b.dataset.anchor==='start'?0:b.dataset.anchor==='end'?records.points.length-1:records.points.findIndex(p=>p.epoch===2);chartMode='loss';renderChart();}
  if(b.dataset.token!==undefined){tokenPosition=Number(b.dataset.token);renderTokens();}
  if(b.id==='token-next'){tokenPosition=(tokenPosition+1)%10;renderTokens();}
  if(b.dataset.demo){demo=demoTransition(demo,b.dataset.demo);renderDemo();}
  if(b.dataset.chart){chartMode=b.dataset.chart;document.querySelectorAll('[data-chart]').forEach(e=>{e.classList.toggle('active',e===b);e.setAttribute('aria-pressed',e===b);});renderChart();}
  if(b.id==='record-start'){recordIndex=0;renderChart();}if(b.id==='record-end'){recordIndex=records.points.length-1;renderChart();}
  if(b.dataset.term!==undefined){selectedTerm=Number(b.dataset.term);renderTermPrinciple();}
  if(b.id==='quiz-retry'){answers={};submitted=false;quizLocked.clear();render();}
  if(b.id==='quiz-wrong'){quizLocked=new Set(questions.map((q,i)=>answers[i]===q.answer?i:-1).filter(i=>i>=0));answers=Object.fromEntries([...quizLocked].map(i=>[i,answers[i]]));submitted=false;render();const first=questions.findIndex((q,i)=>!quizLocked.has(i));$(`#question-${first} input`).focus();}
  if(b.hasAttribute('data-complete')){
    if(current==='quiz'&&(!submitted||gradeQuiz(answers)<questions.length)){notify('先完成六道题，并根据解释修正答案。');return;}
    if(!saved.completed.includes(current))saved.completed.push(current);if(!save())notify('进度暂存于本页，本地保存不可用。');renderNav();if(current==='tokens')demo=initialDemo(1,toyParameter);
    const i=sections.findIndex(s=>s.id===current);if(i<sections.length-1)location.hash=sections[i+1].id;else{notify(completionMessage(saved.completed));render();}
  }
  if(b.id==='menu-button'){const opened=$('#sidebar').classList.toggle('open');b.setAttribute('aria-expanded',opened);syncSidebar();}
  if(b.id==='notes-toggle'||b.hasAttribute('data-open-notes'))openNotes();
  if(b.id==='notes-close')$('#notes-panel').close();
  if(b.id==='notes-download')downloadNotes();
});
function refreshMap(){document.querySelectorAll('[data-stage]').forEach(e=>{const selected=Number(e.dataset.stage)===stage;e.classList.toggle('selected',selected);e.setAttribute('aria-pressed',selected);});$('#stage-detail').innerHTML=stageDetail();$('.step-count').textContent=`STEP ${String(stage+1).padStart(2,'0')} / 08`;$('[data-stage-prev]').disabled=stage===0;$('[data-stage-next]').textContent=stage===7?'从头再走一遍':'下一步 →';}
document.addEventListener('input',event=>{
  const e=event.target;
  if(e.id==='token-position'){tokenPosition=Number(e.value);renderTokens();}
  if(e.id==='toy-score'){toyParameter=Number(e.value);renderToy();}
  if(e.id==='demo-start'){demo=initialDemo(demo.accumulation,Number(e.value));renderDemo();}
  if(e.id==='record-position'){recordIndex=Number(e.value);renderChart();}
  if(e.id==='notes'){saved.notes=e.value;$('#notes-status').textContent=save()?'已自动保存到当前浏览器':'本地保存不可用，请下载笔记';}
});
document.addEventListener('change',event=>{if(event.target.name?.startsWith('question-')){answers[Number(event.target.name.split('-')[1])]=Number(event.target.value);if($('#answered-count'))$('#answered-count').textContent=`已作答 ${Object.keys(answers).length} / ${questions.length}`;}});
document.addEventListener('submit',event=>{if(event.target.id==='quiz-form'){event.preventDefault();if(Object.keys(answers).length!==questions.length){notify('请先完成所有题目。');return;}submitted=true;render();$('#question-0').scrollIntoView({behavior:'smooth',block:'start'});}});
function openNotes(){$('#notes').value=saved.notes;$('#notes-status').textContent=saved.notes?'已保存到当前浏览器':'尚未填写笔记';$('#notes-panel').showModal();$('#notes-toggle').setAttribute('aria-expanded','true');}
$('#notes-panel').addEventListener('close',()=>$('#notes-toggle').setAttribute('aria-expanded','false'));
function downloadNotes(){const content=`# MiniMind 第一课 · 我的学习笔记\n\n${saved.notes||'尚未填写笔记'}\n\n已标记理解：${saved.completed.map(id=>sections.find(s=>s.id===id).title).join('、')||'无'}\n`;const url=URL.createObjectURL(new Blob([content],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='MiniMind-第一课-我的笔记.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('笔记副本已开始下载。');}
window.addEventListener('hashchange',()=>{if(location.hash==='#terms'&&current!=='terms')termReturn=current;render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');syncSidebar();}});
render();
